        cmpa    #$07
        beq     L3572
        cmpa    #$14
        beq     L3572
        ldab    <AISSubIndex
        brclr   <BitFlags71,#$80,L355D               ; engine not running (stopped or cranking)
        ldaa    <EngineRpm_HB
