; DecideToUseDecelFuelCut  ($3966)
;
; Decides whether deceleration fuel cut-off is allowed. [reviewed - data flow]
;
; Requires closed-throttle deceleration with RPM between the DCLRPL / DCLRPH limits relative to
; the target idle speed, coolant above DCLMCT and running time above DCLMER; sets the decel flags
; used by the fuel code. Called from the AIS decel logic.
;
; Called from: AisState13_ClosedThrottle, AisState5_ClosedThrottle
;---------------------------------------------------------------------------------------------------
DecideToUseDecelFuelCut:
        brset   <b58_IPL1,#$40,L39BD
        brset   <BitFlags_AIS,#$08,L39BD
        ldaa    <KeyOnOrEngineRunningTime
        cmpa    >DCLMER_MinTimeEngineRunningForDecelFuelShutoff ; DCLMER (MinTimeEngineRunningForDecelFuelShutoff)
        bls     L39BD
        ldaa    <CoolantTemp
        cmpa    >DCLMCT_MinCoolantTempForDecelFuelShutoff ; DCLMCT (MinCoolantTempForDecelFuelShutoff)
        bls     L39BD
        ldd     <EngineRpm_HB
        subd    <TargetIdleSpeedHB
        bcc     L39B4
        clra
L39B4:
        brclr   <BitFlags6a,#$02,L39C2
        cmpa    >DCLRPL_EngineRPMLimitForDecelFuelShutoffLow ; DCLRPL: Low RPM to activate decel fuel shutoff. Should be lower than shutoff R
        bhi     L39DB
L39BD:
        bclr    <BitFlags6a,#$02
        bra     L39DE

L39C2:
        cmpa    >DCLRPH_EngineRPMLimitForDecelFuelShutoffHigh ; DCLRPH: High RPM to activate decel fuel shutoff. Should be lower than shutoff
        bls     L39DE
        ldaa    >LC5D6                               ; AISCLD: Idle Speed From temp in Drive, auto trans only
        bita    #$08
        bne     L39D8
        brclr   <OutputDriverBits,#$01,L39DB         ; A/C clutch relay
        ldaa    >BYTEc57f                            ; DLYRPM: Decel AIS RPM trigger (third AIS delay)
        staa    >Var_04AE
L39D8:
        bset    <BitFlags6a,#$02
L39DB:
        bset    <BitFlags76,#$10
L39DE:
        rts


