        ldaa    >AISHLM_AisHighLimitMaxOpenSteps     ; AISHLM (AisHighLimitMaxOpenSteps)
L4225:
        staa    <DesiredNewAisPosition
        ldaa    #$B7
        mul
        adca    #$00
        ldy     $06,x
        adda    $00,y
        bcc     L4236
        ldaa    #$FF
L4236:
        ldy     $08,x
        staa    $00,y
        sec
        bra     L4240

L423F:
        clc
L4240:
        rts


